#!/usr/bin/env python3
"""Full French per-passage gist for The Refuge (book 8). Draft, pending native review."""
import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "content", "gist", "the-refuge", "fr.json")
G = {
1: "C'est la pire nuit de l'hiver, et le voile blanc tombe vite avec la nuit. La neige file devant l'unique fenêtre, et la montagne se perd dans le blanc. Puis la vieille Marta, qui garde ce refuge depuis trente hivers, tombe de l'échelle de la soupente et ne peut se relever. Le poêle est bas, la lampe éteinte, et aucune équipe ne peut monter avant le matin. Tenir le refuge, c'est à vous maintenant.",
2: "Vous rassemblez ce que tient la cabane : un bidon de pétrole lampant, des allumettes, une bonne lampe-tempête, une brassée de bois sec. Dehors, le vent hurle et le froid passe droit sous la porte. La neige s'y glisse déjà, blanche. Il faut décider quoi faire, et vite.",
3: "Vous essayez la radio. Elle grésille, puis enfin la voix de Kerr passe depuis le poste du vallon. Aucune équipe ne peut monter avant le matin, dit-il — pas dans un voile blanc pareil. Garde le poêle allumé et la lampe à la fenêtre, vous dit-il, et tiens bon si tu le peux.",
4: "Vous rejoignez Marta au pied de l'échelle et la mettez au chaud et à l'aise. Mais la cabane est froide et la fenêtre sombre. L'abri seul ne suffit pas. Quiconque est pris dehors a besoin de la lampe allumée et du poêle en marche. Il vous faut du combustible, un plan et la tête claire.",
5: "Vous sortez dans la tempête. Le vent manque de vous renverser, et la neige file à plat, blanche. Le froid pèse sur toute la montagne comme une main. Puis, loin en bas de la pente, vous l'apercevez : une petite lumière qui bouge, là où personne ne devrait être ce soir.",
6: "Vous vous forcez à réfléchir. Allumer le poêle et la lampe d'abord et penser au reste après. Ou aller vers Marta et les marcheurs du dortoir. Ou réveiller la vallée pour avoir des bras. Chaque choix coûte un temps que vous n'avez pas — et dehors, le froid travaille déjà quiconque est pris.",
8: "Le froid se pose sur votre poitrine comme un poids. Vous pensez aux gens dehors : un marcheur perdu sur la pente, et la cabane seule chaleur à des lieues. Si la fenêtre reste sombre trop longtemps, le froid les prend avant l'aube. Ce n'est pas une peur, c'est un fait. Personne d'autre ne viendra. C'est vous, cette nuit, ou personne.",
9: "Doune ouvre en grand la réserve de combustible et lève la lampe. Dedans : un fût de pétrole, des allumettes, des fagots de bois sec, de la toile. « Prends ce qu'il faut, dit-il. Je reste près de la radio et j'appelle qui je peux. » C'est un homme solide, et une nuit pareille le montre.",
10: "Vous frappez le long des couchettes, et le vieux Breck ouvre, pâle de froid. Son petit poêle s'est éteint, ses allumettes sont finies, et ses mains tremblent trop pour en frotter une. « Je n'arrive pas à l'allumer », dit-il. Une longue nuit dure vous attend. Mais il est là, effrayé, et c'est vous qu'il implore.",
11: "Vous allez droit au poêle et allumez ce que vous pouvez. Une allumette, une flambée de petit bois, une flamme basse qui prend dans la grille. Mais le feu est maigre et la lampe vacille. Sans vrai combustible, ils ne tiendront pas une heure. Vous ne pouvez pas juste les allumer et espérer.",
12: "Vous allez de porte en porte avec les mêmes mots. Apportez du bois pour le poêle. Donnez un coup de main. Aidez-moi à tenir la lampe à la fenêtre. Certains se détournent et ferment. Mais quelques-uns enfilent leur manteau et sortent dans le froid. Cette nuit, quelques-uns suffisent pour commencer.",
13: "Vous prenez vous-même en charge le combustible et le bois sec. Le fût est lourd, et chaque goutte de pétrole compte à présent. Bien utilisé, il garde le poêle et la lampe toute la nuit ; gâché, la cabane devient froide et noire avant l'aube. Alors vous le serrez contre vous et vous mettez au travail.",
14: "Vous ne prenez qu'une lampe-tempête et une brassée de petit bois. De quoi voir et lancer une flamme. Mais pas le poêle lui-même, et vous n'avez mis aucun vrai combustible de côté. Il vous en faudra, et vite. Sinon, la fenêtre reste sombre et le froid gagne.",
15: "Le vieux Doune a parcouru cette montagne dans le noir plus que quiconque. « Reste loin de la corniche au-dessus du cirque, dit-il. Ça semble un raccourci. Non — c'est une longue chute. » Il vous met aussi en garde contre Vane, cet homme souriant de la compagnie. « Soigne ton combustible, tiens la lampe — c'est tout le travail de ce soir. »",
16: "Vous faites tirer le poêle et installez Breck à côté avec une couverture. Peu à peu, son tremblement s'apaise. « Dieu te bénisse », dit-il en vous serrant fort la main. Vous promettez de repasser avant le matin. Puis vous ressortez vers le froid et la fenêtre sombre.",
17: "Garder la cabane chaude et éclairée passe d'abord. Le reste peut attendre un instant. Mais comment ? Vous pourriez prendre du vrai combustible à la réserve d'abord. Ou aller droit au poêle et à la lampe.",
18: "Le travail vous épuise. Les jambes brûlent, la poitrine halète, et le vent vous combat à chaque pas. Vous êtes au bout de vos forces, et vous le savez. Si vous tombez ici, il ne reste personne pour tenir la cabane. Alors allez lentement, prudemment.",
19: "La vallée se réveille, et les gens se mettent à bouger. Un homme charge un fût de combustible. Une femme sort du bois sec et des lampes frontales. De porte en porte, un plan prend forme. Vous n'êtes plus seul. Et cela change tout.",
20: "Personne ne bouge. Les portes restent closes, les visages se détournent des fenêtres. Ils ont peur, et les gens effrayés se taisent. Vous ne pouvez pas les forcer à monter là-dedans. Alors vous repartez seul. C'est plus dur ainsi. Mais les gens dehors ne peuvent pas les attendre.",
21: "Le poêle tire et la lampe est à la fenêtre. Maintenant la réserve lointaine et le dépôt de combustible. Deux chemins pour l'atteindre. Le long sentier qui contourne le cirque est sûr mais lent. La corniche, tout droit, est rapide. Mais par une nuit pareille, elle pourrait céder.",
22: "Vous prenez à cœur les mots du vieux Doune. Soignez le combustible. Restez loin de la corniche. Ne faites pas confiance à Vane. Et tenez la lampe à la fenêtre avant tout. Conseil simple, et bon. Reste à le suivre.",
23: "Le bon geste vous raffermit. Aider quelqu'un vous raffermit aussi, curieusement. La tête plus claire, les mains plus sûres. La nuit sera encore dure. Mais vous vous sentez capable de l'affronter.",
24: "Un homme surgit de la neige, une lanterne au poing — Vane. Il a du combustible à vendre et des bras à prêter, et il sourit trop facilement. « Le refuge, ce n'est pas vraiment ton affaire ce soir, l'ami », dit-il. Vous avez déjà vu des hommes comme lui.",
25: "Vous menez une petite troupe vers la cabane. Ensemble, vous vous sentez plus forts. Ils portent du combustible, du bois, des torches. « Par ici ! » criez-vous dans le vent, et ils suivent. Cela fait du bien, dans une heure si dure.",
26: "Le sentier est noir et dur, le vent le balaie, aucun abri nulle part. Mais il est ferme sous vos pieds, et il mène où il faut. Alors vous marchez, pas après pas.",
27: "La corniche réduirait la route de moitié, la réserve juste au-delà. Mais le bord est mince et la neige meuble au-dessus d'une longue chute mortelle. Doune vous a dit de ne pas y aller — et il ne plaisantait pas.",
28: "Vous posez le pied sur la corniche, et aussitôt cela sonne faux. Le vide attend dessous, noir, lointain, glacé. Chaque pas est un pari — et vous y êtes, seul. Plus de retour une fois engagé.",
29: "Le bois est humide et ne prend pas. Il ne donne qu'une flamme basse et enfumée. Peu utile par un froid pareil. Il faudra faire avec. Ou retourner à la réserve chercher du bois sec.",
30: "Le sentier continue le long de la pente, le froid plus profond d'heure en heure. En contrebas, un abri sombre, sans feu. Devant, l'air immobile et dur semble vous repousser. Et un poteau indicateur, à demi enseveli dans la neige gelée.",
31: "Un marcheur est tombé dans la neige et ne peut se relever. Le froid le gagne déjà. Vous arrêter, c'est perdre un temps que vous n'avez pas. Ne pas le faire, et il pourrait ne pas tenir l'heure.",
32: "Un groupe est enfermé dans un abri gelé — pas de feu, pas de lampe, un enfant qui pleure dans le noir. Les adultes vous regardent, épuisés, sans espoir. Vous avez une lampe et un manteau. Peu de chose, mais plus qu'eux.",
33: "Vous poussez à travers le pire du froid, chaque pas un combat, la neige mordant votre visage. Des choix devant vous. Vane peut-être. Cette lumière étrange sur la pente. Ou foncer droit vers la cabane.",
34: "Vous remettez le marcheur debout et le réchauffez de votre mieux. Ses yeux se mouillent. Il vous met une paire de moufles sèches dans les mains. « Prends-les, dit-il, pour ta peine. » Petite chose — mais donnée de bon cœur. Vous la prenez et repartez.",
35: "Vous ne pouvez pas rester — mais pas les laisser non plus. Alors vous promettez d'envoyer de l'aide. « Tenez bon ! criez-vous. Restez au chaud, restez ensemble — je ne vous oublie pas. » Et vous le pensez. Puis vous repartez.",
36: "La vallée allume un grand feu de signal sur la colline — un fût de bois embrasé, qui jette lumière et chaleur dans la tempête. On se presse autour, les vieux et les faibles au plus près. Ce n'est pas la nuit gagnée. Mais c'est une vraie chaleur, et un début.",
37: "Abri après abri, la vallée effrayée devient une vallée au travail. Chacun a sa tâche : l'un soigne le feu, l'un porte le bois, l'un surveille la pente. La peur devient action. Et l'action vaut mieux que l'attente, à chaque fois.",
38: "Le long froid ronge votre volonté. Une petite voix dit : arrête, rentre, repose-toi — personne ne t'en voudrait, ce serait si facile. Mais vous pensez aux gens sur la pente. Et vous chassez la voix. Pas encore. Pas tant qu'on peut les atteindre.",
39: "Vous atteignez le vieux poteau, mais la neige l'a enseveli et à demi renversé. On le lit à peine. Un bras montre le sentier. L'autre montre la pente. Quel chemin ? Il faudra deviner, et deviner juste.",
40: "Vane vous adresse son large sourire facile. « Dur travail, ça, dit-il. J'ai du combustible à vendre et des bras à prêter — et le refuge, ce n'est pas vraiment ton affaire ce soir, l'ami. » Sa lanterne se balance. Son sourire n'atteint jamais ses yeux.",
41: "L'offre est un hameçon, et vous le sentez mordre. Il se penche. « Ce refuge est déjà perdu, dit-il tout bas. Laisse le froid l'emporter — et il y a une part pour toi. » C'est cruel à dire. Et c'est fait pour travailler votre peur.",
42: "Vous lui tournez le dos et le laissez à son commerce glacé. Cela fait du bien de partir. Il crie derrière vous, mais vous ne vous retournez pas. Son genre trouve toujours quelqu'un, à la fin. Mais pas vous, pas ce soir.",
43: "Vous prenez son combustible et son marché. Vos mains se referment dessus, et quelque chose en vous sait déjà. Son sourire s'élargit. « Sage », dit-il. Mais ça n'a rien de sage. C'est comme une porte qui se ferme doucement.",
44: "Vous lui demandez tout net : que veut-il vraiment, et pourquoi le refuge devrait-il tomber ? Il sourit et regarde vers la neige. « La terre est bon marché après une mauvaise année, dit-il. Une nuit pareille est une faveur — pour un acheteur comme moi. »",
45: "Vous portez son combustible au poêle. Mais en le versant, la flamme s'étouffe et crache. Il est dilué, coupé d'eau — il ne nourrit pas le feu. La flamme tombe, basse, brune, inutile.",
46: "Vous ouvrez le bidon, et l'odeur vous saisit — ténue, âcre, coupée d'eau. Ce combustible ne nourrira jamais une flamme. Vous l'avez payé cher, et il ne vaut rien. Le doute dans vos tripes avait raison.",
47: "Vous le cherchez, mais la lanterne de Vane est déjà partie dans la neige. Il ne vous aidait pas. Il attendait la tempête, la nuit perdue, la terre bon marché après. On vous a dupé, tout simplement.",
48: "Il est parti, et la pente est vide — rien que le froid, le noir, et ce que vous lui avez donné pour rien. Vous avez appris une dure leçon. Et payée bien trop cher. Vous continuez avec moins qu'au départ.",
49: "Les gens effrayés lui mettent leur argent dans les mains. Les poings pleins de billets, les voix suppliant du combustible. Il prend son temps, avec ce même sourire. Il choisit qui aider selon qui paie le plus.",
50: "Loin sur la corniche, l'autre bord semble plus proche — ou non ? Vous n'en êtes plus sûr. Le noir trompe, et vos yeux fatigués aussi. Et vous voilà loin des deux bords.",
51: "La corniche, le noir, la longue chute dessous — et une fissure court sous votre pied. C'est l'instant. Tomber avec la neige dans le noir. Ou vous rejeter en arrière, tant que vous le pouvez encore.",
52: "Vous atteignez l'autre bord enfin, trempé, tremblant, les mains en sang — mais passé. On ne sait comment, vous y êtes. Maintenant il faut choisir : pousser plus loin, épuisé, ou affronter ce que vous avez perdu sur la corniche.",
53: "Vous vous rejetez en arrière tant que vous le pouvez — le choix dur, le bon. Vous rampez la dernière partie à quatre pattes et gagnez la terre ferme, secoué et lent. La nuit n'est pas perdue. Mais cela vous a coûté un temps qui manquera.",
54: "Vous tentez de rallumer leur poêle et bloquez le pire des courants d'air avec des sacs et une vieille planche. Cela retient un peu le froid. Mais il n'y a pas de lampe à leur laisser, et la nuit est loin d'être finie.",
55: "Vous leur donnez votre manteau et votre lampe, et le groupe se blottit autour de la petite flamme, le soulagement sur les visages. L'enfant cesse enfin de pleurer. « Merci », dit la mère — puis elle vous montre une lumière, sur la pente.",
56: "Sans manteau, le froid et l'humide vous trouvent vite — les dents qui claquent, les doigts raidis. Vous l'avez donné pour aider, et vous le referiez. Mais la tempête s'en moque. Elle mord plus fort, c'est tout.",
57: "Un inconnu vous fait signe d'entrer sous un porche éclairé. « Juste une minute, dit-il. Hors du froid — reprends souffle. » C'est chaud et sec, et tout votre corps supplie de rester. Mais une telle minute glisse vite vers une heure.",
58: "Vous poussez dans la tempête, transi jusqu'aux os. Le froid combat chaque pas. Vos yeux pleurent et piquent. Chaque pas est une petite bataille. Mais vous les enchaînez, l'un après l'autre, vers la cabane.",
60: "Quelqu'un montre la pente : un marcheur est parti par là, seul, dans le froid et le noir. Là-bas, rien que la neige et la longue chute meurtrière. Si personne n'y va, il pourrait ne pas revenir.",
61: "Vous le trouvez sur la pente, à demi gelé et perdu, le froid le déchirant. Il ne semble pas reconnaître votre visage. Vous le prenez fermement par le bras. « Viens avec moi, dites-vous. C'est fini. Je te tiens. »",
62: "Vous ne pouvez pas tout faire, et le refuge a le plus besoin de vous. Alors vous envoyez quelqu'un d'autre à sa recherche et poussez plus loin. Cela vous pèse — mais cette nuit, il faut choisir, encore et encore.",
63: "Vous le ramenez sain et sauf à l'abri, où ses amis crient de soulagement. On vous enveloppe d'un manteau sec et on vous fait une place près du poêle. « Merci », répètent-ils. Mais la cabane attend, et vous ne pouvez rester.",
64: "Vous regardez toute la montagne — toute blanche, toute immobile. La neige gît pâle et profonde dans le noir. Aucune lumière nulle part, sauf sur la pente. Toute la montagne semble retenir son souffle et attendre l'aube.",
65: "Le froid tombe à son pire. Le baromètre descend aussi bas qu'il peut, et votre souffle reste blanc dans l'air immobile. Dur de penser, de bouger, de s'en soucier. C'est l'heure la plus dure de toute la nuit.",
67: "Le vieux Doune vous met la dernière lampe sèche dans les mains. « Pour la fenêtre, dit-il. Vas-y — je reste ici avec Marta et la radio. » Son visage est gris d'inquiétude. C'est l'aide qu'il peut donner ce soir, et il la donne de tout cœur.",
68: "À la réserve, on se rue sur les bidons — les voix montent, les mains s'arrachent, la peur gagne vite. Un coup d'épaule de plus et c'est la bagarre. Vous pouvez tenter de calmer et partager équitablement. Ou prendre le vôtre et filer.",
69: "Un bivouac étouffé de neige vous enserre — blanc, silencieux, froid profond, un lieu où rien ne semble vivant. Puis vous l'entendez : une respiration, faible et proche, sous la neige. Quelqu'un est vivant ici, après tout.",
70: "Loin sur la pente, une petite lumière s'élève et s'éteint. Là où personne ne devrait être ce soir — elle paraît, disparaît, reparaît. Nul ne peut l'expliquer. Et quelque chose en vous veut aller y répondre.",
71: "Vous gagnez la pente et appelez dans le noir. Rien que le vent répond. Puis vous la voyez : une petite forme, dans la neige, à demi cachée dans le blanc. Quelqu'un est dehors, après tout. Et il bouge à peine.",
72: "Vous l'atteignez, et le cœur vous chavire. C'est un jeune marcheur — Rowan — recroquevillé dans la neige, à demi gelé, à peine conscient. Le froid le tient. Pas le temps d'attendre. Il faut agir, maintenant.",
73: "Vous rappelez dans le noir, et un instant, rien. Puis une voix fluette revient, déchirée par le froid : « Ici ! Par ici ! » Quelqu'un est sur la pente, et a besoin d'aide. Et il n'a pas l'air fort du tout.",
74: "Vous sortez Rowan de la neige et l'enveloppez dans votre manteau. Lentement il revient à lui, agrippé à votre bras. « La lampe, souffle-t-il. Garde la lampe à la fenêtre... » Même là, à demi gelé, il pense à la cabane.",
75: "Vous vous tournez pour courir chercher de l'aide — puis vous vous arrêtez net. Pas d'aide dehors, pas avant le matin. Pas d'équipe, pas de vallée, personne. C'est vous ou personne, et Rowan le sait aussi. Ses yeux effrayés vous suivent dans le noir.",
76: "Rowan lève les yeux, le regard plus clair. « La gardienne, Marta — c'est ma grand-mère, dit-il. On ne se parle plus. Pas depuis que mon père et elle se sont fâchés. C'est une longue et triste histoire. » Et vous entendez combien elle est longue.",
77: "Vous décidez de les réunir avant la fin de la nuit — Rowan et la vieille Marta, après toutes ces années. Petite chose, à côté de la tempête et du froid. Mais pas rien. Certaines portes fermées peuvent encore s'ouvrir.",
78: "La petite forme ne bouge pas, et le froid la travaille, lent et patient. Et pourtant quelqu'un est venu jusqu'ici, dans le noir, seul. Vous ne pouvez pas le laisser là. Il faut approcher et savoir qui c'est.",
79: "Vous approchez, et vous le reconnaissez aussitôt. C'est Rowan — le petit-enfant de la vieille Marta, qu'on n'a pas vu ici depuis des années, depuis la brouille de la famille. Puis un faible bruit monte de la neige, à vos pieds. Vous faites vite.",
80: "Vane revient une dernière fois, sa lanterne se balançant. « Toujours à lutter ? dit-il. Laisse le froid l'emporter. Dernière chance d'être du côté des gagnants, l'ami. » Le même sourire facile. Le même vieux mensonge.",
90: "Vous revoilà au refuge, transi, le pire froid de la nuit pesant sur tout. Près de l'échelle, Marta gît grise et immobile. Le poêle brûle bas, la fenêtre est terne. C'est l'heure où tout se joue.",
91: "Vous atteignez le poêle : la flamme basse, la fenêtre éteinte. Sur la pente, le froid est près de prendre quiconque est encore dehors. Il faut remettre le poêle à plein et la lampe vive — et tout de suite, vite.",
92: "Alors l'aide vous rejoint enfin — plus de bras, plus de combustible, des gens solides qui connaissent le travail. Vous n'êtes plus seul ; d'autres partagent le poids. C'est comme poser quelque chose de lourd porté bien trop longtemps.",
93: "Maintenant vous gardez la cabane chaude et éclairée — et ce que vous pouvez faire dépend de ce que vous avez rapporté. Avec du vrai combustible, de quoi travailler. Sans, il faut tirer le moindre reste de flamme. Dans tous les cas, la nuit est loin d'être finie.",
94: "Vous allez voir Marta, et ses yeux s'ouvrent un peu. De la peur dedans — puis, en vous voyant, un peu moins. « Tu l'as tenue », murmure-t-elle. « Oui, dites-vous doucement. Repose-toi maintenant. »",
95: "Le combustible fait l'affaire. Vous nourrissez le poêle et réglez la mèche, et la flamme monte pleine et dorée. La fenêtre brûle vive contre la tempête. Une chaleur qui repousse tout ce froid. Voilà, pensez-vous, à quoi a servi toute cette dure nuit.",
96: "Pas de vrai combustible à verser : vous tirez le peu de flamme qui reste. Vous la protégez du courant d'air de votre corps, la nourrissant de bribes, de souffle, de pure volonté. Elle brûle basse et maigre. Ce ne sera peut-être pas assez. Mais vous ne la laisserez pas mourir sans lutter.",
97: "La flamme est basse et faiblit, et vous craignez que la protéger seul ne suffise pas. Vous avez fait tout ce que vous pouviez avec ce que vous aviez. Mais ça pourrait ne pas tenir. Il vous faut plus — plus de combustible, plus de bras, ou les deux.",
98: "Vous jetez un œil dehors et vous la voyez. Loin sur la pente, une lumière jaillit et retombe — là où personne ne devrait être, paraissant et se cachant. Elle attire votre œil. Et quelque chose de plus profond.",
99: "La lumière sur la pente reparaît — là où tous jurent que personne ne serait. Mais une lumière suppose une main, et une main suppose une personne. Une personne, dehors, seule, dans un froid pareil.",
100: "Vient alors la longue veille : vous nourrissez le poêle, gardez Marta au chaud, surveillez le froid heure après heure. Rien d'excitant — juste un travail régulier, dur, soigneux. Mais c'est tout le travail de ce soir, et il est à vous.",
101: "Et puis, enfin, ça tourne. Le vent desserre un peu son étreinte. Le ciel grisonne au bord de la crête, et la première lueur vient. Le froid perd. Vous avez presque tenu toute la nuit.",
102: "C'est l'heure la plus dure, juste avant la rupture. Le froid n'a pas cédé ; les bras font mal, les yeux brûlent. Mais vous sentez la nuit commencer à tourner, quelque part dessous. Tenez encore un peu.",
103: "Sur la colline, vous les voyez — des torches, des silhouettes sombres, des feux bas contre la neige. D'autres gens, dehors dans le froid comme vous. La vallée aussi a traversé cette nuit. Vous n'étiez pas aussi seul qu'il semblait.",
104: "Enfin, l'aide monte la colline — l'équipe, plus de bras, plus de combustible, une vraie aide à bonne allure. Vous vous appuyez à la porte et la regardez venir, les jambes tremblantes. Mais le pire de la nuit est derrière vous.",
105: "L'aube monte sur la montagne, la lumière devient grise, puis pâle et nette. Le soleil passe la crête, et le froid lâche prise. La lampe brûle toujours à la fenêtre. Le pire est enfin passé.",
106: "Puis il vient — le premier oiseau du matin, chantant sur la neige comme s'il n'y avait eu aucune tempête. Après la nuit que vous avez eue, c'est presque absurde. Et c'est beau, et vous vous arrêtez pour l'écouter.",
107: "De la fenêtre, vous guettez la pente, où une lumière s'élève, retombe, et grandit lentement. Quelque chose vient enfin, encore trop loin pour qu'on distingue. Mais une lumière veut dire quelqu'un — et quelqu'un vaut bien mieux que personne cette nuit.",
110: "La première lueur vient enfin, et la nuit fait ses comptes. Tout ce que vous avez fait dehors, dans le froid, revient à vous — de quoi être fier, et de quoi l'être moins. Voyons donc à quoi tout cela a mené.",
111: "La nuit s'additionne — non par un grand geste, mais par mille petits. Ce que vous avez gardé, ce que vous avez refusé, pour qui vous êtes sorti dans le froid. Tout compte, à la fin. Tout a fait la nuit telle qu'elle fut.",
112: "Il reste à peser ; la nuit tenait d'autres choses. Un inconnu pour qui vous vous êtes arrêté. Un manteau, une lampe donnés d'une main ouverte. Petits choix, faits dans le froid, quand il aurait été plus simple de passer.",
113: "Et que vous laisse la nuit ? Peut-être pas une victoire nette. Peut-être juste ceci : que vous êtes sorti, que vous avez essayé. Quand il était noir, froid, facile de barrer la porte, vous ne l'avez pas fait. Cela compte.",
114: "Mais toutes les nuits ne finissent pas bien. Certains choix coûtent plus qu'on ne croyait ; certaines portes, une fois ouvertes, ne se referment plus. C'est la fin dure de la nuit — là où le pire revient à vous.",
120: "Vous avez tenu le poêle tirant et la lampe vive à la fenêtre toute la nuit. À la première lueur, le nuage se lève sur la crête, l'équipe vous rejoint, et tous ceux que la montagne tenait ce soir sont ramenés au chaud. Tout a tenu parce que vous êtes resté debout et n'avez pas laissé la lumière mourir. C'est tout.",
121: "Vous avez répondu à la lumière que nul ne pouvait expliquer. Vous avez trouvé Rowan, perdu et transi sous la corniche, et l'avez rentré et réchauffé juste à temps. Et plus d'une vie fut sauvée : Rowan est le petit-enfant de Marta. Une porte fermée depuis des années s'ouvre à nouveau, dans le gris de l'aube.",
122: "Il n'y eut pas un seul acte de bravoure — il y eut mieux. Vous avez changé une vallée endormie en gens munis de torches sur la colline, et ensemble ils ont traversé la nuit. Personne n'y fut laissé seul. Voilà, au fond, ce que peut être une vallée.",
123: "Vous avez refusé l'arnaque — vu le tour de Vane et lui avez tourné le dos. Vous avez gardé la tête froide et tenu le refuge par des moyens honnêtes. Nuit imparfaite ; vous n'avez pas ramené tout le monde. Mais c'était propre, et propre suffit.",
124: "Vous n'avez pas réussi à tout tenir. Mais le marcheur pour qui vous vous étiez arrêté revient. Il vous aide à garder la cabane et à réchauffer Marta. Pas la pleine victoire. Mais une gentillesse, il se trouve, revient toujours.",
125: "Vous avez donné votre manteau et votre combustible à plus démunis que vous, et finissez la nuit transi vous-même. Vous n'avez pas tout sauvé. Mais vous n'êtes pas seul, ni personne de ceux que vous avez croisés. Quelque chose a bougé dans la vallée. C'est un début, pas un sauvetage.",
126: "Vous passez de justesse. Le vent tombe enfin, et une aube maigre amène l'équipe sur la colline. Pas un triomphe, et nul n'en chantera. Mais vous avez traversé la nuit — et au fond, c'est déjà un soulagement.",
127: "Vous n'avez pas ramené tout le monde. Mais la vallée vous a vu sur la colline quand d'autres barraient leur porte — vous a vu essayer, la pire nuit de l'année. À partir de ce soir, vous êtes quelqu'un que ce lieu connaît. Et ce n'est pas rien.",
128: "Vous avez pris le marché de Vane, et au matin le refuge est condamné — à personne désormais. Le froid a fait le reste. L'argent dans votre poche est froid, et la fenêtre est noire. Vous n'oublierez pas de sitôt comment vous l'avez gagné.",
129: "La corniche était un piège, comme Doune l'avait dit. Elle a cédé sous vous dans le noir, et a pris toute la nuit. Vous vous traînez dehors, blessé et gelé, et atteignez l'autre bord bien trop tard. La corniche vous a coûté tout ce que le raccourci promettait.",
130: "Vous avez passé la nuit sur les mauvaises choses, et le poêle est resté éteint trop longtemps. À l'aube, la cabane est froide, et quiconque était sur la pente n'a pas été trouvé à temps. Vous êtes sorti dans le froid. Mais vous n'avez pas gardé la lumière quand il le fallait.",
131: "À la fin, vous êtes resté dedans, au chaud et en sûreté. Vous vous êtes dit que la tempête était trop dure, que ce n'était pas votre affaire, que l'aide viendrait à l'aube. Tout cela était vrai. Et toute la nuit, dehors, la fenêtre est restée sombre. Rien de mal ne vous est arrivé. Vous y penserez longtemps, très longtemps.",
}
def main():
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    data = json.load(open(OUT, encoding="utf-8")) if os.path.exists(OUT) else {}
    a = 0
    for nid, t in G.items():
        k = str(nid)
        if k not in data: a += 1
        data[k] = t
    data = {k: data[k] for k in sorted(data, key=lambda x: int(x))}
    json.dump(data, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("the-refuge/fr.json: %d (+%d)" % (len(data), a))
if __name__ == "__main__":
    main()
